(function () {

    /*
     * ============================================================
     * PORTSMOUTH TOWN COUNCIL YOUTUBE WIDGET
     * ============================================================
     */

    const API_KEY = "AIzaSyDjfV2Ss7He_rEtQ318S-pmCGjeNTRzwdw";

    const CHANNEL_ID =
        "UCOwlnQCR0Uge45gTnIt2G_Q";

    /*
     * We will look through the channel's most recent uploads
     * and select the newest video whose title appears to be
     * a Town Council video.
     */

    const MAX_VIDEOS_TO_CHECK = 25;

    /*
     * Words that indicate the video is a Town Council video.
     */

    const COUNCIL_TERMS = [
        "town council",
        "town council meeting",
        "portsmouth town council",
        "town council regular meeting",
        "town council special meeting",
        "town council workshop",
        "town council public hearing"
    ];

    /*
     * Words that should cause a video to be rejected.
     *
     * This prevents a Planning Board, Zoning Board, etc.
     * from being displayed just because the title contains
     * the word "meeting".
     */

    const EXCLUDE_TERMS = [
        "planning board",
        "zoning board",
        "school committee",
        "school board",
        "conservation commission",
        "recreation commission",
        "harbor commission",
        "budget committee",
        "library board",
        "fire district",
        "water authority",
        "economic development",
        "historic district",
        "board of canvassers"
    ];


    function getStatusElement() {
        return document.getElementById(
            "council-video-status"
        );
    }


    function showError(message) {

        console.error(
            "Portsmouth Town Council video:",
            message
        );

        const status =
            document.getElementById(
                "council-video-status"
            );

        const error =
            document.getElementById(
                "council-video-error"
            );

        if (status) {
            status.style.display = "none";
        }

        if (error) {
            error.style.display = "block";
        }
    }


    function normalizeTitle(title) {

        return (title || "")
            .toLowerCase()
            .replace(/\s+/g, " ")
            .trim();
    }


    function isCouncilVideo(title) {

        const normalized =
            normalizeTitle(title);

        /*
         * Reject known non-Council meetings first.
         */

        for (const term of EXCLUDE_TERMS) {

            if (normalized.includes(term)) {
                return false;
            }

        }

        /*
         * Then look for Council terminology.
         */

        for (const term of COUNCIL_TERMS) {

            if (normalized.includes(term)) {
                return true;
            }

        }

        return false;
    }


    async function youtubeRequest(
        endpoint,
        parameters
    ) {

        const url =
            new URL(
                "https://www.googleapis.com/youtube/v3/" +
                endpoint
            );

        Object.entries(parameters)
            .forEach(([key, value]) => {

                url.searchParams.set(
                    key,
                    value
                );

            });

        const response =
            await fetch(url.toString());

        if (!response.ok) {

            let details = "";

            try {
                details = await response.text();
            } catch (e) {
                details = "";
            }

            throw new Error(
                "YouTube API HTTP " +
                response.status +
                ": " +
                details
            );
        }

        return response.json();
    }


    async function getUploadsPlaylist() {

        /*
         * The channel resource tells us which playlist
         * contains the channel's uploaded videos.
         */

        const data =
            await youtubeRequest(
                "channels",
                {
                    part: "contentDetails",
                    id: CHANNEL_ID,
                    key: API_KEY
                }
            );

        if (
            !data.items ||
            !data.items.length
        ) {

            throw new Error(
                "YouTube channel not found."
            );

        }

        return data.items[0]
            .contentDetails
            .relatedPlaylists
            .uploads;
    }


    async function getRecentVideos(
        playlistId
    ) {

        const data =
            await youtubeRequest(
                "playlistItems",
                {
                    part: "snippet,contentDetails",
                    playlistId: playlistId,
                    maxResults: MAX_VIDEOS_TO_CHECK,
                    key: API_KEY
                }
            );

        return data.items || [];
    }


    function displayVideo(video) {

        const videoId =
            video.contentDetails.videoId;

        const title =
            video.snippet.title;

        const published =
            video.contentDetails.videoPublishedAt ||
            video.snippet.publishedAt;

        /*
         * Use YouTube's normal embed domain.
         *
         * We already tested this successfully
         * on the Portsmouth website.
         */

        const embedUrl =
            "https://www.youtube.com/embed/" +
            encodeURIComponent(videoId) +
            "?rel=0&playsinline=1";


        const iframe =
            document.getElementById(
                "council-video-iframe"
            );

        const player =
            document.getElementById(
                "council-video-player"
            );

        const status =
            document.getElementById(
                "council-video-status"
            );

        const info =
            document.getElementById(
                "council-video-info"
            );


        iframe.src = embedUrl;

        player.style.display = "block";

        status.style.display = "none";

        /*
         * Display the title/date below the player.
         */

        let dateText = "";

        if (published) {

            const date =
                new Date(published);

            if (!isNaN(date.getTime())) {

                dateText =
                    " • " +
                    date.toLocaleDateString(
                        "en-US",
                        {
                            year: "numeric",
                            month: "long",
                            day: "numeric"
                        }
                    );

            }

        }


        info.innerHTML =
            "<strong>" +
            escapeHtml(title) +
            "</strong>" +
            dateText;

        info.style.display = "block";

        console.log(
            "Portsmouth Town Council video:",
            title,
            videoId
        );
    }


    function escapeHtml(value) {

        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    async function loadLatestCouncilVideo() {

        try {

            if (
                !API_KEY ||
                API_KEY ===
                "YOUR_YOUTUBE_API_KEY"
            ) {

                throw new Error(
                    "YouTube API key has not been configured."
                );

            }

            getStatusElement().textContent =
                "Loading latest Town Council video...";


            /*
             * Step 1:
             * Find the channel's uploads playlist.
             */

            const uploadsPlaylist =
                await getUploadsPlaylist();


            /*
             * Step 2:
             * Get the newest uploads.
             */

            const videos =
                await getRecentVideos(
                    uploadsPlaylist
                );


            /*
             * Step 3:
             * Find the newest Council video.
             *
             * YouTube returns the uploads in reverse
             * chronological order, so the first matching
             * video is the newest matching Council video.
             */

            const councilVideo =
                videos.find(video => {

                    const title =
                        video.snippet &&
                        video.snippet.title
                            ? video.snippet.title
                            : "";

                    return isCouncilVideo(title);

                });


            if (!councilVideo) {

                throw new Error(
                    "No Town Council video found " +
                    "among the latest " +
                    MAX_VIDEOS_TO_CHECK +
                    " channel uploads."
                );

            }


            displayVideo(councilVideo);

        }
        catch (error) {

            showError(error.message);

        }

    }


    loadLatestCouncilVideo();

})();


	

	

	 

	 

							
	

		


	 

	 

							
	

		
 
	
	
		
	

	

	 

	 

			 


	






